inline std::string_view enumName(const EnumEntry* tbl, std::size_t n,
                                  std::int32_t v) {
    for (std::size_t i = 0; i < n; ++i)
        if (tbl[i].value == v) return tbl[i].name;
    return {};
}

// Case-sensitive name -> value. Accepts the full constant or the value
// as decimal. Returns false if unresolved.
inline bool enumValue(const EnumEntry* tbl, std::size_t n,
                      std::string_view name, std::int32_t& out) {
    for (std::size_t i = 0; i < n; ++i)
        if (tbl[i].name == name) { out = tbl[i].value; return true; }
    return false;
}

inline std::string_view gameActionName(std::int32_t v) {
    return enumName(kGameActionEnum, sizeof(kGameActionEnum) / sizeof(kGameActionEnum[0]), v);
}
inline bool gameActionValue(std::string_view name, std::int32_t& out) {
    return enumValue(kGameActionEnum, sizeof(kGameActionEnum) / sizeof(kGameActionEnum[0]), name, out);
}

